/* eslint-disable no-nested-ternary */
import axios from 'src/utils/axios';

/** ---- TYPES CÔTÉ API ---- */
export type RafType = 'free' | 'paid';
export type ServerRoundStatus = 'SELLING' | 'WAITING' | 'DRAWING' | 'FINISHED';
export type UiPhase = 'selling' | 'waiting' | 'drawing' | 'finished';

export interface RafSummary {
  raf_id: number;
  raf_name: string;
  type: RafType;
  stake: number;
  postSellDelayMin: number;
  payoutsMultipliers: number[]; // ex: [50,20,10]
  limitPerUser: number | null;
  ballsCount: number; // ex: 99
  round_code: string;
  status: ServerRoundStatus;
  sold: number; // nb de boules déjà vendues
}

export interface RoundState {
  round_code: string;
  raf: {
    id: number;
    name: string;
    type: RafType;
    stake: number;
    postSellDelayMin: number;
    payoutsMultipliers: number[];
    limitPerUser: number | null;
    ballsCount: number;
  };
  purchased: { all: string[]; mine: string[] }; // "01".. "99"
  status: 'ongoing' | 'waiting' | 'drawing' | 'end';
  results?: { result_1: string; result_2: string; result_3: string } | null;
  sold: number;
}

/** ---- HELPERS ---- */
export const toUiPhase = (s: ServerRoundStatus): UiPhase =>
  s === 'SELLING' ? 'selling' : s === 'WAITING' ? 'waiting' : s === 'DRAWING' ? 'drawing' : 'finished';

/** ---- API CALLS ---- */
export async function listActiveRafs(): Promise<RafSummary[]> {
  const { data } = await axios.post('/api/v1/raf/rounds/', { action: 'list' });
  // data = { result: true, data: RafSummary[] }
  return data.data as RafSummary[];
}

export async function getRoundState(round_code: string): Promise<RoundState> {
  const { data } = await axios.post('/api/v1/raf/rounds/', { action: 'state', round_code });
  return data.data as RoundState;
}

export async function buyNumbers(params: {
  raf_id: number;
  round_code: string;
  numbers: string[]; // ["11","43","32"]
}): Promise<{
  ticket_id: string;
  total_paid: number;
  numbers: string[];
  round_code: string;
  status: ServerRoundStatus | 'WAITING' | 'DRAWING' | 'FINISHED';
}> {
  const { data } = await axios.post('/api/v1/raf/receipts/?action=add', params);
  return data.data;
}

export async function getMoney(): Promise<number> {
  const { data } = await axios.post('/api/v1/raf/money/', {});
  return Number(data?.data?.money ?? 0);
}
